CREATE   PROCEDURE dbo.usp_merge_legacy_enriched      @payload NVARCHAR(MAX)  AS  BEGIN      SET NOCOUNT ON;        ;WITH src AS (          SELECT *          FROM OPENJSON(@payload, '$.results')          WITH (              [Customer]        NVARCHAR(100) '$."Customer"',              [Name 1]          NVARCHAR(255) '$."Name 1"',              [Name 2]          NVARCHAR(255) '$."Name 2"',              [Name 3]          NVARCHAR(255) '$."Name 3"',              [Name 4]          NVARCHAR(255) '$."Name 4"',              [Domain]          NVARCHAR(255) '$."Domain"',              [Department Domain]          NVARCHAR(255) '$."Department Domain"',              [Search Term 1]   NVARCHAR(255) '$."Search Term 1"',              [Search Term 2]   NVARCHAR(255) '$."Search Term 2"',              [Care Of]         NVARCHAR(255) '$."Care Of"',              [Contact]         NVARCHAR(255) '$."Contact"',              [Email]           NVARCHAR(255) '$."Email"',              [Street 1]        NVARCHAR(255) '$."Street 1"',              [House Number]    NVARCHAR(50)  '$."House Number"',              [Street 2]        NVARCHAR(255) '$."Street 2"',              [Street 3]        NVARCHAR(255) '$."Street 3"',              [Street 4]        NVARCHAR(255) '$."Street 4"',              [Street 5]        NVARCHAR(255) '$."Street 5"',              [PO Box]          NVARCHAR(100) '$."PO Box"',              [Suite]           NVARCHAR(100) '$."Suite"',              [Building]        NVARCHAR(100) '$."Building"',              [Floor]           NVARCHAR(100) '$."Floor"',              [Room]            NVARCHAR(100) '$."Room"',              [Unit]            NVARCHAR(100) '$."Unit"',              [Mail Stop]       NVARCHAR(100) '$."Mail Stop"',              [Unloading]       NVARCHAR(100) '$."Unloading Point"',              [Mail Code]       NVARCHAR(100) '$."Mail Code"',              [Record Type]     NVARCHAR(100) '$."Record Type"',              [ROR ID]          NVARCHAR(255) '$."ROR ID"',              [LEI ID]          NVARCHAR(100) '$."LEI ID"',              [Flag for Review] BIT           '$."Flag for Review"',              [Flag Reason]     NVARCHAR(500) '$."Flag Reason"'          )      )      MERGE dp_legacy.test_77.Legacy AS tgt      USING src ON tgt.Customer = src.Customer      WHEN MATCHED THEN UPDATE SET          tgt.[Name 1]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 1])),''),        tgt.[Name 1]),          tgt.[Name 2]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 2])),''),        tgt.[Name 2]),          tgt.[Name 3]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 3])),''),        tgt.[Name 3]),          tgt.[Name 4]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[Name 4])),''),        tgt.[Name 4]),          tgt.[Domain]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[Domain])),''),        tgt.[Domain]),          tgt.[Department Domain]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[Department Domain])),''),        tgt.[Department Domain]),          tgt.[Search Term 1] = COALESCE(NULLIF(LTRIM(RTRIM(src.[Search Term 1])),''), tgt.[Search Term 1]),          tgt.[Search Term 2] = COALESCE(NULLIF(LTRIM(RTRIM(src.[Search Term 2])),''), tgt.[Search Term 2]),          tgt.[Care Of]       = COALESCE(NULLIF(LTRIM(RTRIM(src.[Care Of])),''),       tgt.[Care Of]),          tgt.[Contact]       = COALESCE(NULLIF(LTRIM(RTRIM(src.[Contact])),''),       tgt.[Contact]),          tgt.[Email]         = COALESCE(NULLIF(LTRIM(RTRIM(src.[Email])),''),         tgt.[Email]),          tgt.[Street 1]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 1])),''),      tgt.[Street 1]),          tgt.[House Number]  = COALESCE(NULLIF(LTRIM(RTRIM(src.[House Number])),''),  tgt.[House Number]),          tgt.[Street 2]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 2])),''),      tgt.[Street 2]),          tgt.[Street 3]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 3])),''),      tgt.[Street 3]),          tgt.[Street 4]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 4])),''),      tgt.[Street 4]),          tgt.[Street 5]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[Street 5])),''),      tgt.[Street 5]),          tgt.[PO Box]        = COALESCE(NULLIF(LTRIM(RTRIM(src.[PO Box])),''),        tgt.[PO Box]),          tgt.[Suite]         = COALESCE(NULLIF(LTRIM(RTRIM(src.[Suite])),''),         tgt.[Suite]),          tgt.[Building]      = COALESCE(NULLIF(LTRIM(RTRIM(src.[Building])),''),      tgt.[Building]),          tgt.[Floor]         = COALESCE(NULLIF(LTRIM(RTRIM(src.[Floor])),''),         tgt.[Floor]),          tgt.[Room]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Room])),''),          tgt.[Room]),          tgt.[Unit]          = COALESCE(NULLIF(LTRIM(RTRIM(src.[Unit])),''),          tgt.[Unit]),          tgt.[Mail Stop]     = COALESCE(NULLIF(LTRIM(RTRIM(src.[Mail Stop])),''),     tgt.[Mail Stop]),          tgt.[Unloading]     = COALESCE(NULLIF(LTRIM(RTRIM(src.[Unloading])),''),     tgt.[Unloading]),          tgt.[Mail Code]     = COALESCE(NULLIF(LTRIM(RTRIM(src.[Mail Code])),''),     tgt.[Mail Code]),          tgt.[Record Type]     = LTRIM(RTRIM(src.[Record Type])),          tgt.[ROR ID]          = LTRIM(RTRIM(src.[ROR ID])),          tgt.[LEI ID]          = LTRIM(RTRIM(src.[LEI ID])),          tgt.[Flag for Review] = src.[Flag for Review],          tgt.[Flag Reason]     = src.[Flag Reason];  END